    AUD_ACCION VARCHAR2(20),
    CONSTRAINT FIDE_ROL_ESTADO_ID_FK FOREIGN KEY (ESTADO_ID) REFERENCES FIDE_ESTADO_TB(ESTADO_ID)
);

