CREATE TABLE FIDE_DIRECCION_TB (
    DIRECCION_ID NUMBER CONSTRAINT FIDE_DIRECCION_DIRECCION_ID_PK PRIMARY KEY,
    DETALLE_DIRECCION VARCHAR2(250),
    USUARIO_ID NUMBER,
    PROVINCIA_ID NUMBER,
    CANTON_ID NUMBER,
    DISTRITO_ID NUMBER,
    ESTADO_ID NUMBER,
    AUD_CREADO_POR VARCHAR2(100),
    AUD_FECHA_CREACION TIMESTAMP(6),
    AUD_MODIFICADO_POR VARCHAR2(100),
    AUD_FECHA_MODIFICACION TIMESTAMP(6),
    AUD_ACCION VARCHAR2(20),
    CONSTRAINT FIDE_DIRECCION_USUARIO_ID_FK FOREIGN KEY (USUARIO_ID) REFERENCES FIDE_USUARIOS_TB(USUARIO_ID),
    CONSTRAINT FIDE_DIRECCION_PROVINCIA_ID_FK FOREIGN KEY (PROVINCIA_ID) REFERENCES FIDE_PROVINCIA_TB(PROVINCIA_ID),
    CONSTRAINT FIDE_DIRECCION_CANTON_ID_FK FOREIGN KEY (CANTON_ID) REFERENCES FIDE_CANTON_TB(CANTON_ID),
    CONSTRAINT FIDE_DIRECCION_DISTRITO_ID_FK FOREIGN KEY (DISTRITO_ID) REFERENCES FIDE_DISTRITO_TB(DISTRITO_ID),
    CONSTRAINT FIDE_DIRECCION_ESTADO_ID_FK FOREIGN KEY (ESTADO_ID) REFERENCES FIDE_ESTADO_TB(ESTADO_ID)
);

CREATE TABLE FIDE_PEDIDOS_TB (
    PEDIDO_ID NUMBER CONSTRAINT FIDE_PEDIDOS_PEDIDO_ID_PK PRIMARY KEY,
    FECHA_PEDIDO DATE,
    FECHA_ENTREGA DATE,
    USUARIO_ID NUMBER,
    ESTADO_ID NUMBER,
