    AUD_FECHA_CREACION TIMESTAMP(6),
    AUD_MODIFICADO_POR VARCHAR2(100),
    AUD_FECHA_MODIFICACION TIMESTAMP(6),
    AUD_ACCION VARCHAR2(20),
    CONSTRAINT FIDE_PEDIDOS_USUARIO_ID_FK FOREIGN KEY (USUARIO_ID) REFERENCES FIDE_USUARIOS_TB(USUARIO_ID),
    CONSTRAINT FIDE_PEDIDOS_ESTADO_ID_FK FOREIGN KEY (ESTADO_ID) REFERENCES FIDE_ESTADO_TB(ESTADO_ID)
);

CREATE TABLE FIDE_DETALLE_PEDIDOS_TB (
