    AUD_ACCION VARCHAR2(20),
    CONSTRAINT FIDE_DETALLE_PEDIDOS_INVENTARIO_ID_FK FOREIGN KEY (INVENTARIO_ID) REFERENCES FIDE_INVENTARIO_TB(INVENTARIO_ID),
    CONSTRAINT FIDE_DETALLE_PEDIDOS_PEDIDO_ID_FK FOREIGN KEY (PEDIDO_ID) REFERENCES FIDE_PEDIDOS_TB(PEDIDO_ID),
    CONSTRAINT FIDE_DETALLE_PEDIDOS_ESTADO_ID_FK FOREIGN KEY (ESTADO_ID) REFERENCES FIDE_ESTADO_TB(ESTADO_ID)
);

CREATE TABLE FIDE_CONTABILIDAD_TB (
    CONTABILIDAD_ID NUMBER CONSTRAINT FIDE_CONTABILIDAD_CONTABILIDAD_ID_PK PRIMARY KEY,
    DESCRIPCION_CONTA VARCHAR2(250),
