    CONSTRAINT FIDE_CONTABILIDAD_PEDIDO_ID_FK FOREIGN KEY (PEDIDO_ID) REFERENCES FIDE_PEDIDOS_TB(PEDIDO_ID),
    CONSTRAINT FIDE_CONTABILIDAD_ACTIVO_ID_FK FOREIGN KEY (ACTIVO_ID) REFERENCES FIDE_ACTIVOS_TB(ACTIVO_ID),
    CONSTRAINT FIDE_CONTABILIDAD_ESTADO_ID_FK FOREIGN KEY (ESTADO_ID) REFERENCES FIDE_ESTADO_TB(ESTADO_ID)
);

CREATE TABLE FIDE_TRANSPORTE_TB (
    TRANSPORTE_ID NUMBER CONSTRAINT FIDE_TRANSPORTE_TRANSPORTE_ID_PK PRIMARY KEY,
