    CONSTRAINT FIDE_TRANSPORTE_PEDIDO_ID_FK FOREIGN KEY (PEDIDO_ID) REFERENCES FIDE_PEDIDOS_TB(PEDIDO_ID),
    CONSTRAINT FIDE_TRANSPORTE_USUARIO_ID_FK FOREIGN KEY (USUARIO_ID) REFERENCES FIDE_USUARIOS_TB(USUARIO_ID),
    CONSTRAINT FIDE_TRANSPORTE_ACTIVO_ID_FK FOREIGN KEY (ACTIVO_ID) REFERENCES FIDE_ACTIVOS_TB(ACTIVO_ID),
    CONSTRAINT FIDE_TRANSPORTE_ESTADO_ID_FK FOREIGN KEY (ESTADO_ID) REFERENCES FIDE_ESTADO_TB(ESTADO_ID)
);


--------------------------------------FUNCIONES---------------------------------

CREATE OR REPLACE FUNCTION FIDE_ESTADO_ID_FN(P_DESCRIPCION_ESTADO IN VARCHAR2)
RETURN NUMBER IS
    V_ID NUMBER;
    CURSOR C_ESTADO IS
        SELECT ESTADO_ID FROM FIDE_ESTADO_TB
        WHERE UPPER(DESCRIPCION_ESTADO) = UPPER(TRIM(P_DESCRIPCION_ESTADO));
BEGIN
    FOR I IN C_ESTADO LOOP
        V_ID := I.ESTADO_ID;
    END LOOP;
    RETURN V_ID;
EXCEPTION
    WHEN TOO_MANY_ROWS THEN
        DBMS_OUTPUT.PUT_LINE('Se encontraron varios registros');
        RAISE;
    WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE('No se encontraron datos');
        RAISE;
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Error:' || SQLERRM);
        RAISE;
END FIDE_ESTADO_ID_FN;
/


CREATE OR REPLACE FUNCTION FIDE_DESCRIPCION_ESTADO_FN(P_ESTADO_ID IN NUMBER)
RETURN VARCHAR2 IS
    V_DESC VARCHAR2(100);
    CURSOR C_ESTADO IS
        SELECT DESCRIPCION_ESTADO FROM FIDE_ESTADO_TB WHERE ESTADO_ID = P_ESTADO_ID;
BEGIN
    FOR I IN C_ESTADO LOOP
        V_DESC := I.DESCRIPCION_ESTADO;
    END LOOP;
    RETURN V_DESC;
EXCEPTION
    WHEN TOO_MANY_ROWS THEN
        DBMS_OUTPUT.PUT_LINE('Se encontraron varios registros');
        RAISE;
    WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE('No se encontraron datos');
        RAISE;
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Error:' || SQLERRM);
        RAISE;
END FIDE_DESCRIPCION_ESTADO_FN;
/


CREATE OR REPLACE FUNCTION FIDE_NOMBRE_USUARIO_FN(P_USUARIO_ID IN NUMBER)
RETURN VARCHAR2 IS
    V_NOMBRE VARCHAR2(300);
    CURSOR C_USUARIO IS
        SELECT NOMBRE_USUARIO || ' ' || APELLIDO_PATERNO || ' ' || APELLIDO_MATERNO AS NOMBRE_COMPLETO
        FROM FIDE_USUARIOS_TB WHERE USUARIO_ID = P_USUARIO_ID;
BEGIN
    FOR I IN C_USUARIO LOOP
        V_NOMBRE := TRIM(I.NOMBRE_COMPLETO);
    END LOOP;
    RETURN V_NOMBRE;
EXCEPTION
    WHEN TOO_MANY_ROWS THEN
        DBMS_OUTPUT.PUT_LINE('Se encontraron varios registros');
        RAISE;
    WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE('No se encontraron datos');
        RAISE;
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Error:' || SQLERRM);
        RAISE;
END FIDE_NOMBRE_USUARIO_FN;
/


CREATE OR REPLACE FUNCTION FIDE_TOTAL_PEDIDO_FN(P_PEDIDO_ID IN NUMBER)
RETURN NUMBER IS
    V_TOTAL NUMBER := 0;
    CURSOR C_DETALLE IS
        SELECT CANTIDAD_PEDIDO, PRECIO_UNITARIO FROM FIDE_DETALLE_PEDIDOS_TB WHERE PEDIDO_ID = P_PEDIDO_ID;
BEGIN
    FOR I IN C_DETALLE LOOP
        V_TOTAL := V_TOTAL + (I.CANTIDAD_PEDIDO * I.PRECIO_UNITARIO);
    END LOOP;
    RETURN V_TOTAL;
EXCEPTION
    WHEN TOO_MANY_ROWS THEN
        DBMS_OUTPUT.PUT_LINE('Se encontraron varios registros');
        RAISE;
    WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE('No se encontraron datos');
        RAISE;
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Error:' || SQLERRM);
        RAISE;
END FIDE_TOTAL_PEDIDO_FN;
/


CREATE OR REPLACE FUNCTION FIDE_CALCULAR_IVA_FN(P_MONTO IN NUMBER, P_PORCENTAJE IN NUMBER DEFAULT 13)
RETURN NUMBER IS
BEGIN
    RETURN ROUND(P_MONTO * P_PORCENTAJE / 100, 2);
EXCEPTION
    WHEN TOO_MANY_ROWS THEN
        DBMS_OUTPUT.PUT_LINE('Se encontraron varios registros');
        RAISE;
    WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE('No se encontraron datos');
        RAISE;
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Error:' || SQLERRM);
        RAISE;
END FIDE_CALCULAR_IVA_FN;
/


CREATE OR REPLACE FUNCTION FIDE_TOTAL_CON_IVA_FN(P_MONTO IN NUMBER, P_PORCENTAJE IN NUMBER DEFAULT 13)
RETURN NUMBER IS
BEGIN
    RETURN P_MONTO + FIDE_CALCULAR_IVA_FN(P_MONTO, P_PORCENTAJE);
EXCEPTION
    WHEN TOO_MANY_ROWS THEN
        DBMS_OUTPUT.PUT_LINE('Se encontraron varios registros');
        RAISE;
    WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE('No se encontraron datos');
        RAISE;
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Error:' || SQLERRM);
        RAISE;
END FIDE_TOTAL_CON_IVA_FN;
/


