CREATE OR REPLACE FUNCTION FIDE_TELEFONOS_CONTACTO_FN(P_CONTACTO_ID IN NUMBER)
RETURN VARCHAR2 IS
    V_RESULTADO VARCHAR2(4000);
    CURSOR C_TEL IS
        SELECT NUMERO FROM FIDE_TELEFONO_TB WHERE CONTACTO_ID = P_CONTACTO_ID ORDER BY TELEFONO_ID;
BEGIN
    FOR I IN C_TEL LOOP
        IF V_RESULTADO IS NULL THEN
            V_RESULTADO := I.NUMERO;
        ELSE
            V_RESULTADO := V_RESULTADO || ', ' || I.NUMERO;
        END IF;
    END LOOP;
    RETURN V_RESULTADO;
EXCEPTION
    WHEN TOO_MANY_ROWS THEN
        DBMS_OUTPUT.PUT_LINE('Se encontraron varios registros');
        RAISE;
    WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE('No se encontraron datos');
        RAISE;
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Error:' || SQLERRM);
        RAISE;
END FIDE_TELEFONOS_CONTACTO_FN;
