-- Secuencia numerica con fecha -----------------------------------------
CREATE OR REPLACE FUNCTION FIDE_SECUENCIA_NUMERICA_FN(P_NUEVO_VALOR IN NUMBER)
RETURN NUMBER IS
    V_FECHA VARCHAR2(8);
BEGIN
    V_FECHA := TO_CHAR(SYSDATE, 'YYYYMMDD');
    RETURN TO_NUMBER(V_FECHA || LPAD(MOD(P_NUEVO_VALOR, 100000), 5, '0'));
EXCEPTION
    WHEN TOO_MANY_ROWS THEN
        DBMS_OUTPUT.PUT_LINE('Se encontraron varios registros');
        RAISE;
    WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE('No se encontraron datos');
        RAISE;
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Error:' || SQLERRM);
        RAISE;
END FIDE_SECUENCIA_NUMERICA_FN;
/

--------------- VISTAS------------------------------------

CREATE OR REPLACE VIEW FIDE_USUARIOS_V AS
SELECT U.USUARIO_ID, U.NOMBRE_USUARIO, U.APELLIDO_PATERNO, U.APELLIDO_MATERNO, U.FECHA_CREACION,
       R.NOMBRE_ROL, E.DESCRIPCION_ESTADO
FROM FIDE_USUARIOS_TB U
LEFT JOIN FIDE_ROL_TB R ON U.ROL_ID = R.ROL_ID
LEFT JOIN FIDE_ESTADO_TB E ON U.ESTADO_ID = E.ESTADO_ID;


CREATE OR REPLACE VIEW FIDE_ACTIVOS_V AS
SELECT A.ACTIVO_ID, A.NOMBRE_ACTIVO, A.FECHA_ADQUISICION, T.NOMBRE_ACTIVO AS TIPO_ACTIVO, E.DESCRIPCION_ESTADO
FROM FIDE_ACTIVOS_TB A
LEFT JOIN FIDE_TIPO_ACTIVO_TB T ON A.TIPO_ACTIVO_ID = T.TIPO_ACTIVO_ID
LEFT JOIN FIDE_ESTADO_TB E ON A.ESTADO_ID = E.ESTADO_ID;


CREATE OR REPLACE VIEW FIDE_PEDIDOS_V AS
SELECT P.PEDIDO_ID, P.FECHA_PEDIDO, P.FECHA_ENTREGA, P.USUARIO_ID,
       U.NOMBRE_USUARIO || ' ' || U.APELLIDO_PATERNO AS CLIENTE,
       E.DESCRIPCION_ESTADO,
       (SELECT NVL(SUM(D.CANTIDAD_PEDIDO * D.PRECIO_UNITARIO), 0)
          FROM FIDE_DETALLE_PEDIDOS_TB D
         WHERE D.PEDIDO_ID = P.PEDIDO_ID) AS TOTAL_PEDIDO
FROM FIDE_PEDIDOS_TB P
LEFT JOIN FIDE_USUARIOS_TB U ON P.USUARIO_ID = U.USUARIO_ID
LEFT JOIN FIDE_ESTADO_TB E ON P.ESTADO_ID = E.ESTADO_ID;


CREATE OR REPLACE VIEW FIDE_DETALLE_PEDIDOS_V AS
SELECT D.DETALLE_PEDIDO_ID, D.PEDIDO_ID, I.NOMBRE_PRODUCTO, D.CANTIDAD_PEDIDO, D.PRECIO_UNITARIO,
       D.CANTIDAD_PEDIDO * D.PRECIO_UNITARIO AS SUBTOTAL, P.FECHA_PEDIDO, E.DESCRIPCION_ESTADO
FROM FIDE_DETALLE_PEDIDOS_TB D
LEFT JOIN FIDE_INVENTARIO_TB I ON D.INVENTARIO_ID = I.INVENTARIO_ID
LEFT JOIN FIDE_PEDIDOS_TB P ON D.PEDIDO_ID = P.PEDIDO_ID
LEFT JOIN FIDE_ESTADO_TB E ON D.ESTADO_ID = E.ESTADO_ID;


CREATE OR REPLACE VIEW FIDE_GANADO_V AS
SELECT G.GANADO_ID, G.EDAD, R.NOMBRE_RAZA, L.LOTE_ID, L.FECHA_REGISTRO, E.DESCRIPCION_ESTADO
FROM FIDE_GANADO_TB G
LEFT JOIN FIDE_RAZA_TB R ON G.RAZA_ID = R.RAZA_ID
LEFT JOIN FIDE_LOTE_TB L ON G.LOTE_ID = L.LOTE_ID
LEFT JOIN FIDE_ESTADO_TB E ON G.ESTADO_ID = E.ESTADO_ID;


CREATE OR REPLACE VIEW FIDE_INVENTARIO_V AS
SELECT I.INVENTARIO_ID, I.NOMBRE_PRODUCTO, I.CANTIDAD_INVE, TP.NOMBRE_PRODUCTO AS TIPO_PRODUCTO,
       D.DESCRIPCION_DESTI AS DESTINATARIO, E.DESCRIPCION_ESTADO
FROM FIDE_INVENTARIO_TB I
LEFT JOIN FIDE_TIPO_PRODUCTO_TB TP ON I.TIPO_PRODUCTO_ID = TP.TIPO_PRODUCTO_ID
LEFT JOIN FIDE_DESTINATARIO_TB D ON TP.DESTINATARIO_ID = D.DESTINATARIO_ID
LEFT JOIN FIDE_ESTADO_TB E ON I.ESTADO_ID = E.ESTADO_ID;


CREATE OR REPLACE VIEW FIDE_MANTENIMIENTO_V AS
SELECT M.MANTENIMIENTO_ID, M.DESCRIPCION_MANTE, M.FECHA_PROGRAMADA, TM.NOMBRE_MANTENIMIENTO,
       A.NOMBRE_ACTIVO, U.NOMBRE_USUARIO || ' ' || U.APELLIDO_PATERNO AS RESPONSABLE, E.DESCRIPCION_ESTADO
FROM FIDE_MANTENIMIENTO_TB M
LEFT JOIN FIDE_TIPO_MANTENIMIENTO_TB TM ON M.TIPO_MANTENIMIENTO_ID = TM.TIPO_MANTENIMIENTO_ID
LEFT JOIN FIDE_ACTIVOS_TB A ON M.ACTIVO_ID = A.ACTIVO_ID
LEFT JOIN FIDE_USUARIOS_TB U ON M.RESPONSABLE_ID = U.USUARIO_ID
LEFT JOIN FIDE_ESTADO_TB E ON M.ESTADO_ID = E.ESTADO_ID;


CREATE OR REPLACE VIEW FIDE_CONTROL_SANITARIO_V AS
SELECT C.CONTROL_SANITARIO_ID, C.FECHA_REALIZO, C.FECHA_PROXIMO_CONTROL, TC.NOMBRE_CONTROL,
       A.NOMBRE_ACTIVO, U.NOMBRE_USUARIO || ' ' || U.APELLIDO_PATERNO AS RESPONSABLE, E.DESCRIPCION_ESTADO
FROM FIDE_CONTROL_SANITARIO_TB C
LEFT JOIN FIDE_TIPO_CONTROL_TB TC ON C.TIPO_CONTROL_ID = TC.TIPO_CONTROL_ID
LEFT JOIN FIDE_ACTIVOS_TB A ON C.ACTIVO_ID = A.ACTIVO_ID
LEFT JOIN FIDE_USUARIOS_TB U ON C.RESPONSABLE_ID = U.USUARIO_ID
LEFT JOIN FIDE_ESTADO_TB E ON C.ESTADO_ID = E.ESTADO_ID;


CREATE OR REPLACE VIEW FIDE_LABORATORIO_V AS
SELECT L.LABORATORIO_ID, L.RESULTADO, TA.NOMBRE_ANALISIS, L.LOTE_ID,
       U.NOMBRE_USUARIO || ' ' || U.APELLIDO_PATERNO AS RESPONSABLE, E.DESCRIPCION_ESTADO
FROM FIDE_LABORATORIO_TB L
LEFT JOIN FIDE_TIPO_ANALISIS_TB TA ON L.TIPO_ANALISIS_ID = TA.TIPO_ANALISIS_ID
LEFT JOIN FIDE_USUARIOS_TB U ON L.RESPONSABLE_ID = U.USUARIO_ID
LEFT JOIN FIDE_ESTADO_TB E ON L.ESTADO_ID = E.ESTADO_ID;


CREATE OR REPLACE VIEW FIDE_DIRECCIONES_V AS
SELECT D.DIRECCION_ID, U.NOMBRE_USUARIO || ' ' || U.APELLIDO_PATERNO AS USUARIO,
       P.NOMBRE_PROVINCIA, C.NOMBRE_CANTON, DI.NOMBRE_DISTRITO, D.DETALLE_DIRECCION, E.DESCRIPCION_ESTADO
FROM FIDE_DIRECCION_TB D
LEFT JOIN FIDE_USUARIOS_TB U ON D.USUARIO_ID = U.USUARIO_ID
LEFT JOIN FIDE_PROVINCIA_TB P ON D.PROVINCIA_ID = P.PROVINCIA_ID
LEFT JOIN FIDE_CANTON_TB C ON D.CANTON_ID = C.CANTON_ID
LEFT JOIN FIDE_DISTRITO_TB DI ON D.DISTRITO_ID = DI.DISTRITO_ID
LEFT JOIN FIDE_ESTADO_TB E ON D.ESTADO_ID = E.ESTADO_ID;


CREATE OR REPLACE VIEW FIDE_TRANSPORTE_V AS
SELECT T.TRANSPORTE_ID, T.FECHA_ENTREGA, T.CANTIDAD_KG, T.PEDIDO_ID,
       U.NOMBRE_USUARIO || ' ' || U.APELLIDO_PATERNO AS TRANSPORTISTA,
       A.NOMBRE_ACTIVO AS VEHICULO, D.DETALLE_DIRECCION AS DESTINO, E.DESCRIPCION_ESTADO
FROM FIDE_TRANSPORTE_TB T
LEFT JOIN FIDE_USUARIOS_TB U ON T.USUARIO_ID = U.USUARIO_ID
LEFT JOIN FIDE_DIRECCION_TB D ON T.DIRECCION_ID = D.DIRECCION_ID
LEFT JOIN FIDE_ESTADO_TB E ON T.ESTADO_ID = E.ESTADO_ID
LEFT JOIN FIDE_ACTIVOS_TB A ON T.ACTIVO_ID = A.ACTIVO_ID;


CREATE OR REPLACE VIEW FIDE_CONTACTOS_V AS
SELECT C.CONTACTO_ID, C.NOMBRE_CONTACTO, U.NOMBRE_USUARIO || ' ' || U.APELLIDO_PATERNO AS USUARIO,
       (SELECT LISTAGG(T.NUMERO, ', ') WITHIN GROUP (ORDER BY T.TELEFONO_ID)
          FROM FIDE_TELEFONO_TB T WHERE T.CONTACTO_ID = C.CONTACTO_ID) AS TELEFONOS,
       (SELECT LISTAGG(R.DIRECCION_CORREO, ', ') WITHIN GROUP (ORDER BY R.CORREO_ID)
          FROM FIDE_CORREO_TB R WHERE R.CONTACTO_ID = C.CONTACTO_ID) AS CORREOS,
       E.DESCRIPCION_ESTADO
FROM FIDE_CONTACTO_TB C
LEFT JOIN FIDE_USUARIOS_TB U ON C.USUARIO_ID = U.USUARIO_ID
LEFT JOIN FIDE_ESTADO_TB E ON C.ESTADO_ID = E.ESTADO_ID;


