--PAQUETE FIDE_PROYECTO_PCK--------------------------------


CREATE OR REPLACE PACKAGE FIDE_PROYECTO_PCK AS

    -- ===== Secuencias =====
    PROCEDURE FIDE_SIGUIENTE_ID_SP(
        P_SECUENCIA IN VARCHAR2,
        P_ID OUT NUMBER
    );

    -- ===== CRUD (31 tablas) =====
    PROCEDURE FIDE_ESTADO_INSERTAR_SP(
        P_DESCRIPCION_ESTADO IN FIDE_ESTADO_TB.DESCRIPCION_ESTADO%TYPE,
        P_ESTADO_ID OUT FIDE_ESTADO_TB.ESTADO_ID%TYPE
    );

    PROCEDURE FIDE_ESTADO_ACTUALIZAR_SP(
        P_ESTADO_ID IN FIDE_ESTADO_TB.ESTADO_ID%TYPE,
        P_DESCRIPCION_ESTADO IN FIDE_ESTADO_TB.DESCRIPCION_ESTADO%TYPE
    );

    PROCEDURE FIDE_ESTADO_ELIMINAR_SP(
        P_ESTADO_ID IN FIDE_ESTADO_TB.ESTADO_ID%TYPE
    );

    PROCEDURE FIDE_ESTADO_CONSULTAR_SP(
        P_ESTADO_ID IN FIDE_ESTADO_TB.ESTADO_ID%TYPE DEFAULT NULL,
        P_CURSOR OUT SYS_REFCURSOR
    );

    PROCEDURE FIDE_ROL_INSERTAR_SP(
        P_NOMBRE_ROL IN FIDE_ROL_TB.NOMBRE_ROL%TYPE,
        P_DESCRIPCION_ROL IN FIDE_ROL_TB.DESCRIPCION_ROL%TYPE,
        P_ESTADO_ID IN FIDE_ROL_TB.ESTADO_ID%TYPE,
        P_ROL_ID OUT FIDE_ROL_TB.ROL_ID%TYPE
    );

    PROCEDURE FIDE_ROL_ACTUALIZAR_SP(
        P_ROL_ID IN FIDE_ROL_TB.ROL_ID%TYPE,
        P_NOMBRE_ROL IN FIDE_ROL_TB.NOMBRE_ROL%TYPE,
        P_DESCRIPCION_ROL IN FIDE_ROL_TB.DESCRIPCION_ROL%TYPE,
        P_ESTADO_ID IN FIDE_ROL_TB.ESTADO_ID%TYPE
    );

    PROCEDURE FIDE_ROL_ELIMINAR_SP(
        P_ROL_ID IN FIDE_ROL_TB.ROL_ID%TYPE
    );

    PROCEDURE FIDE_ROL_CONSULTAR_SP(
        P_ROL_ID IN FIDE_ROL_TB.ROL_ID%TYPE DEFAULT NULL,
        P_CURSOR OUT SYS_REFCURSOR
    );

    PROCEDURE FIDE_TIPO_ACTIVO_INSERTAR_SP(
        P_NOMBRE_ACTIVO IN FIDE_TIPO_ACTIVO_TB.NOMBRE_ACTIVO%TYPE,
        P_ESTADO_ID IN FIDE_TIPO_ACTIVO_TB.ESTADO_ID%TYPE,
        P_TIPO_ACTIVO_ID OUT FIDE_TIPO_ACTIVO_TB.TIPO_ACTIVO_ID%TYPE
    );

    PROCEDURE FIDE_TIPO_ACTIVO_ACTUALIZAR_SP(
        P_TIPO_ACTIVO_ID IN FIDE_TIPO_ACTIVO_TB.TIPO_ACTIVO_ID%TYPE,
        P_NOMBRE_ACTIVO IN FIDE_TIPO_ACTIVO_TB.NOMBRE_ACTIVO%TYPE,
        P_ESTADO_ID IN FIDE_TIPO_ACTIVO_TB.ESTADO_ID%TYPE
    );

    PROCEDURE FIDE_TIPO_ACTIVO_ELIMINAR_SP(
        P_TIPO_ACTIVO_ID IN FIDE_TIPO_ACTIVO_TB.TIPO_ACTIVO_ID%TYPE
    );

    PROCEDURE FIDE_TIPO_ACTIVO_CONSULTAR_SP(
        P_TIPO_ACTIVO_ID IN FIDE_TIPO_ACTIVO_TB.TIPO_ACTIVO_ID%TYPE DEFAULT NULL,
        P_CURSOR OUT SYS_REFCURSOR
    );

    PROCEDURE FIDE_TIPO_ANALISIS_INSERTAR_SP(
        P_NOMBRE_ANALISIS IN FIDE_TIPO_ANALISIS_TB.NOMBRE_ANALISIS%TYPE,
        P_DESCRIPCION_ANAL IN FIDE_TIPO_ANALISIS_TB.DESCRIPCION_ANAL%TYPE,
        P_ESTADO_ID IN FIDE_TIPO_ANALISIS_TB.ESTADO_ID%TYPE,
        P_TIPO_ANALISIS_ID OUT FIDE_TIPO_ANALISIS_TB.TIPO_ANALISIS_ID%TYPE
    );

    PROCEDURE FIDE_TIPO_ANALISIS_ACTUALIZAR_SP(
        P_TIPO_ANALISIS_ID IN FIDE_TIPO_ANALISIS_TB.TIPO_ANALISIS_ID%TYPE,
        P_NOMBRE_ANALISIS IN FIDE_TIPO_ANALISIS_TB.NOMBRE_ANALISIS%TYPE,
        P_DESCRIPCION_ANAL IN FIDE_TIPO_ANALISIS_TB.DESCRIPCION_ANAL%TYPE,
        P_ESTADO_ID IN FIDE_TIPO_ANALISIS_TB.ESTADO_ID%TYPE
    );

    PROCEDURE FIDE_TIPO_ANALISIS_ELIMINAR_SP(
        P_TIPO_ANALISIS_ID IN FIDE_TIPO_ANALISIS_TB.TIPO_ANALISIS_ID%TYPE
    );

    PROCEDURE FIDE_TIPO_ANALISIS_CONSULTAR_SP(
        P_TIPO_ANALISIS_ID IN FIDE_TIPO_ANALISIS_TB.TIPO_ANALISIS_ID%TYPE DEFAULT NULL,
        P_CURSOR OUT SYS_REFCURSOR
    );

    PROCEDURE FIDE_TIPO_CONTROL_INSERTAR_SP(
        P_NOMBRE_CONTROL IN FIDE_TIPO_CONTROL_TB.NOMBRE_CONTROL%TYPE,
        P_DESCRIPCION_CONTROL IN FIDE_TIPO_CONTROL_TB.DESCRIPCION_CONTROL%TYPE,
        P_ESTADO_ID IN FIDE_TIPO_CONTROL_TB.ESTADO_ID%TYPE,
        P_TIPO_CONTROL_ID OUT FIDE_TIPO_CONTROL_TB.TIPO_CONTROL_ID%TYPE
    );

    PROCEDURE FIDE_TIPO_CONTROL_ACTUALIZAR_SP(
        P_TIPO_CONTROL_ID IN FIDE_TIPO_CONTROL_TB.TIPO_CONTROL_ID%TYPE,
        P_NOMBRE_CONTROL IN FIDE_TIPO_CONTROL_TB.NOMBRE_CONTROL%TYPE,
        P_DESCRIPCION_CONTROL IN FIDE_TIPO_CONTROL_TB.DESCRIPCION_CONTROL%TYPE,
        P_ESTADO_ID IN FIDE_TIPO_CONTROL_TB.ESTADO_ID%TYPE
    );

    PROCEDURE FIDE_TIPO_CONTROL_ELIMINAR_SP(
        P_TIPO_CONTROL_ID IN FIDE_TIPO_CONTROL_TB.TIPO_CONTROL_ID%TYPE
    );

    PROCEDURE FIDE_TIPO_CONTROL_CONSULTAR_SP(
        P_TIPO_CONTROL_ID IN FIDE_TIPO_CONTROL_TB.TIPO_CONTROL_ID%TYPE DEFAULT NULL,
        P_CURSOR OUT SYS_REFCURSOR
    );

    PROCEDURE FIDE_TIPO_MANTENIMIENTO_INSERTAR_SP(
        P_NOMBRE_MANTENIMIENTO IN FIDE_TIPO_MANTENIMIENTO_TB.NOMBRE_MANTENIMIENTO%TYPE,
        P_ESTADO_ID IN FIDE_TIPO_MANTENIMIENTO_TB.ESTADO_ID%TYPE,
        P_TIPO_MANTENIMIENTO_ID OUT FIDE_TIPO_MANTENIMIENTO_TB.TIPO_MANTENIMIENTO_ID%TYPE
    );

    PROCEDURE FIDE_TIPO_MANTENIMIENTO_ACTUALIZAR_SP(
        P_TIPO_MANTENIMIENTO_ID IN FIDE_TIPO_MANTENIMIENTO_TB.TIPO_MANTENIMIENTO_ID%TYPE,
        P_NOMBRE_MANTENIMIENTO IN FIDE_TIPO_MANTENIMIENTO_TB.NOMBRE_MANTENIMIENTO%TYPE,
        P_ESTADO_ID IN FIDE_TIPO_MANTENIMIENTO_TB.ESTADO_ID%TYPE
    );

    PROCEDURE FIDE_TIPO_MANTENIMIENTO_ELIMINAR_SP(
        P_TIPO_MANTENIMIENTO_ID IN FIDE_TIPO_MANTENIMIENTO_TB.TIPO_MANTENIMIENTO_ID%TYPE
    );

