/

-------------PAQUETE FIDE_PROYECTO_BODY_PCK-------------------------------------
CREATE OR REPLACE PACKAGE BODY FIDE_PROYECTO_PCK AS

    PROCEDURE FIDE_SIGUIENTE_ID_SP(
        P_SECUENCIA IN VARCHAR2,
        P_ID OUT NUMBER
    ) IS
    BEGIN
        EXECUTE IMMEDIATE 'SELECT ' || DBMS_ASSERT.SIMPLE_SQL_NAME(P_SECUENCIA) || '.NEXTVAL FROM DUAL'
        INTO P_ID;
    EXCEPTION
        WHEN TOO_MANY_ROWS THEN
            DBMS_OUTPUT.PUT_LINE('Se encontraron varios registros');
            RAISE;
        WHEN NO_DATA_FOUND THEN
            DBMS_OUTPUT.PUT_LINE('No se encontraron datos');
            RAISE;
        WHEN OTHERS THEN
            DBMS_OUTPUT.PUT_LINE('Error:' || SQLERRM);
            RAISE;
    END FIDE_SIGUIENTE_ID_SP;

    PROCEDURE FIDE_ESTADO_INSERTAR_SP(
        P_DESCRIPCION_ESTADO IN FIDE_ESTADO_TB.DESCRIPCION_ESTADO%TYPE,
        P_ESTADO_ID OUT FIDE_ESTADO_TB.ESTADO_ID%TYPE
    ) IS
    BEGIN
        INSERT INTO FIDE_ESTADO_TB (DESCRIPCION_ESTADO)
        VALUES (P_DESCRIPCION_ESTADO)
        RETURNING ESTADO_ID INTO P_ESTADO_ID;
        COMMIT;
    EXCEPTION
        WHEN DUP_VAL_ON_INDEX THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(-20001, 'Ya existe un registro con esos datos en FIDE_ESTADO_TB');
        WHEN TOO_MANY_ROWS THEN
            ROLLBACK;
            DBMS_OUTPUT.PUT_LINE('Se encontraron varios registros');
            RAISE;
        WHEN NO_DATA_FOUND THEN
            ROLLBACK;
            DBMS_OUTPUT.PUT_LINE('No se encontraron datos');
            RAISE;
        WHEN OTHERS THEN
            ROLLBACK;
            DBMS_OUTPUT.PUT_LINE('Error:' || SQLERRM);
            RAISE;
    END FIDE_ESTADO_INSERTAR_SP;

    PROCEDURE FIDE_ESTADO_ACTUALIZAR_SP(
        P_ESTADO_ID IN FIDE_ESTADO_TB.ESTADO_ID%TYPE,
        P_DESCRIPCION_ESTADO IN FIDE_ESTADO_TB.DESCRIPCION_ESTADO%TYPE
    ) IS
    BEGIN
        UPDATE FIDE_ESTADO_TB
        SET DESCRIPCION_ESTADO = P_DESCRIPCION_ESTADO
        WHERE ESTADO_ID = P_ESTADO_ID;
        IF SQL%ROWCOUNT = 0 THEN
            RAISE_APPLICATION_ERROR(-20002, 'No existe el registro en FIDE_ESTADO_TB');
        END IF;
        COMMIT;
    EXCEPTION
        WHEN TOO_MANY_ROWS THEN
            ROLLBACK;
            DBMS_OUTPUT.PUT_LINE('Se encontraron varios registros');
            RAISE;
        WHEN NO_DATA_FOUND THEN
            ROLLBACK;
            DBMS_OUTPUT.PUT_LINE('No se encontraron datos');
            RAISE;
        WHEN OTHERS THEN
            ROLLBACK;
            DBMS_OUTPUT.PUT_LINE('Error:' || SQLERRM);
            RAISE;
    END FIDE_ESTADO_ACTUALIZAR_SP;

    PROCEDURE FIDE_ESTADO_ELIMINAR_SP(
        P_ESTADO_ID IN FIDE_ESTADO_TB.ESTADO_ID%TYPE
    ) IS
    BEGIN
        DELETE FROM FIDE_ESTADO_TB WHERE ESTADO_ID = P_ESTADO_ID;
        IF SQL%ROWCOUNT = 0 THEN
            RAISE_APPLICATION_ERROR(-20002, 'No existe el registro en FIDE_ESTADO_TB');
        END IF;
        COMMIT;
    EXCEPTION
        WHEN TOO_MANY_ROWS THEN
            ROLLBACK;
            DBMS_OUTPUT.PUT_LINE('Se encontraron varios registros');
            RAISE;
        WHEN NO_DATA_FOUND THEN
            ROLLBACK;
            DBMS_OUTPUT.PUT_LINE('No se encontraron datos');
            RAISE;
        WHEN OTHERS THEN
            ROLLBACK;
            DBMS_OUTPUT.PUT_LINE('Error:' || SQLERRM);
            RAISE;
    END FIDE_ESTADO_ELIMINAR_SP;

    PROCEDURE FIDE_ESTADO_CONSULTAR_SP(
        P_ESTADO_ID IN FIDE_ESTADO_TB.ESTADO_ID%TYPE DEFAULT NULL,
        P_CURSOR OUT SYS_REFCURSOR
    ) IS
    BEGIN
        OPEN P_CURSOR FOR
            SELECT ESTADO_ID, DESCRIPCION_ESTADO
            FROM FIDE_ESTADO_TB
            WHERE (P_ESTADO_ID IS NULL OR ESTADO_ID = P_ESTADO_ID)
            ORDER BY ESTADO_ID;
    EXCEPTION
        WHEN TOO_MANY_ROWS THEN
            DBMS_OUTPUT.PUT_LINE('Se encontraron varios registros');
            RAISE;
        WHEN NO_DATA_FOUND THEN
            DBMS_OUTPUT.PUT_LINE('No se encontraron datos');
            RAISE;
        WHEN OTHERS THEN
            DBMS_OUTPUT.PUT_LINE('Error:' || SQLERRM);
            RAISE;
    END FIDE_ESTADO_CONSULTAR_SP;

    PROCEDURE FIDE_ROL_INSERTAR_SP(
        P_NOMBRE_ROL IN FIDE_ROL_TB.NOMBRE_ROL%TYPE,
        P_DESCRIPCION_ROL IN FIDE_ROL_TB.DESCRIPCION_ROL%TYPE,
        P_ESTADO_ID IN FIDE_ROL_TB.ESTADO_ID%TYPE,
        P_ROL_ID OUT FIDE_ROL_TB.ROL_ID%TYPE
    ) IS
    BEGIN
        INSERT INTO FIDE_ROL_TB (NOMBRE_ROL, DESCRIPCION_ROL, ESTADO_ID)
        VALUES (P_NOMBRE_ROL, P_DESCRIPCION_ROL, P_ESTADO_ID)
        RETURNING ROL_ID INTO P_ROL_ID;
        COMMIT;
    EXCEPTION
        WHEN DUP_VAL_ON_INDEX THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(-20001, 'Ya existe un registro con esos datos en FIDE_ROL_TB');
        WHEN TOO_MANY_ROWS THEN
            ROLLBACK;
            DBMS_OUTPUT.PUT_LINE('Se encontraron varios registros');
            RAISE;
        WHEN NO_DATA_FOUND THEN
            ROLLBACK;
            DBMS_OUTPUT.PUT_LINE('No se encontraron datos');
            RAISE;
        WHEN OTHERS THEN
            ROLLBACK;
            DBMS_OUTPUT.PUT_LINE('Error:' || SQLERRM);
            RAISE;
    END FIDE_ROL_INSERTAR_SP;

    PROCEDURE FIDE_ROL_ACTUALIZAR_SP(
        P_ROL_ID IN FIDE_ROL_TB.ROL_ID%TYPE,
        P_NOMBRE_ROL IN FIDE_ROL_TB.NOMBRE_ROL%TYPE,
        P_DESCRIPCION_ROL IN FIDE_ROL_TB.DESCRIPCION_ROL%TYPE,
        P_ESTADO_ID IN FIDE_ROL_TB.ESTADO_ID%TYPE
    ) IS
    BEGIN
        UPDATE FIDE_ROL_TB
        SET NOMBRE_ROL = P_NOMBRE_ROL,
            DESCRIPCION_ROL = P_DESCRIPCION_ROL,
            ESTADO_ID = P_ESTADO_ID
        WHERE ROL_ID = P_ROL_ID;
        IF SQL%ROWCOUNT = 0 THEN
            RAISE_APPLICATION_ERROR(-20002, 'No existe el registro en FIDE_ROL_TB');
        END IF;
        COMMIT;
    EXCEPTION
        WHEN TOO_MANY_ROWS THEN
            ROLLBACK;
            DBMS_OUTPUT.PUT_LINE('Se encontraron varios registros');
