        P_FECHA_MOVIMIENTO IN FIDE_CONTABILIDAD_TB.FECHA_MOVIMIENTO%TYPE,
        P_PEDIDO_ID IN FIDE_CONTABILIDAD_TB.PEDIDO_ID%TYPE,
        P_ACTIVO_ID IN FIDE_CONTABILIDAD_TB.ACTIVO_ID%TYPE,
        P_ESTADO_ID IN FIDE_CONTABILIDAD_TB.ESTADO_ID%TYPE
    ) IS
    BEGIN
        UPDATE FIDE_CONTABILIDAD_TB
        SET DESCRIPCION_CONTA = P_DESCRIPCION_CONTA,
            MONTO = P_MONTO,
            FECHA_MOVIMIENTO = P_FECHA_MOVIMIENTO,
            PEDIDO_ID = P_PEDIDO_ID,
            ACTIVO_ID = P_ACTIVO_ID,
            ESTADO_ID = P_ESTADO_ID
        WHERE CONTABILIDAD_ID = P_CONTABILIDAD_ID;
        IF SQL%ROWCOUNT = 0 THEN
            RAISE_APPLICATION_ERROR(-20002, 'No existe el registro en FIDE_CONTABILIDAD_TB');
        END IF;
        COMMIT;
    EXCEPTION
        WHEN TOO_MANY_ROWS THEN
            ROLLBACK;
            DBMS_OUTPUT.PUT_LINE('Se encontraron varios registros');
            RAISE;
        WHEN NO_DATA_FOUND THEN
            ROLLBACK;
            DBMS_OUTPUT.PUT_LINE('No se encontraron datos');
            RAISE;
        WHEN OTHERS THEN
            ROLLBACK;
            DBMS_OUTPUT.PUT_LINE('Error:' || SQLERRM);
            RAISE;
    END FIDE_CONTABILIDAD_ACTUALIZAR_SP;

