    PROCEDURE FIDE_TRANSPORTE_INSERTAR_SP(
        P_FECHA_ENTREGA IN FIDE_TRANSPORTE_TB.FECHA_ENTREGA%TYPE,
        P_CANTIDAD_KG IN FIDE_TRANSPORTE_TB.CANTIDAD_KG%TYPE,
        P_DIRECCION_ID IN FIDE_TRANSPORTE_TB.DIRECCION_ID%TYPE,
        P_PEDIDO_ID IN FIDE_TRANSPORTE_TB.PEDIDO_ID%TYPE,
        P_USUARIO_ID IN FIDE_TRANSPORTE_TB.USUARIO_ID%TYPE,
        P_ACTIVO_ID IN FIDE_TRANSPORTE_TB.ACTIVO_ID%TYPE,
        P_ESTADO_ID IN FIDE_TRANSPORTE_TB.ESTADO_ID%TYPE,
        P_TRANSPORTE_ID OUT FIDE_TRANSPORTE_TB.TRANSPORTE_ID%TYPE
    ) IS
    BEGIN
        INSERT INTO FIDE_TRANSPORTE_TB (FECHA_ENTREGA, CANTIDAD_KG, DIRECCION_ID, PEDIDO_ID, USUARIO_ID, ACTIVO_ID, ESTADO_ID)
        VALUES (P_FECHA_ENTREGA, P_CANTIDAD_KG, P_DIRECCION_ID, P_PEDIDO_ID, P_USUARIO_ID, P_ACTIVO_ID, P_ESTADO_ID)
        RETURNING TRANSPORTE_ID INTO P_TRANSPORTE_ID;
        COMMIT;
    EXCEPTION
        WHEN DUP_VAL_ON_INDEX THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(-20001, 'Ya existe un registro con esos datos en FIDE_TRANSPORTE_TB');
        WHEN TOO_MANY_ROWS THEN
            ROLLBACK;
            DBMS_OUTPUT.PUT_LINE('Se encontraron varios registros');
            RAISE;
        WHEN NO_DATA_FOUND THEN
            ROLLBACK;
            DBMS_OUTPUT.PUT_LINE('No se encontraron datos');
            RAISE;
        WHEN OTHERS THEN
            ROLLBACK;
            DBMS_OUTPUT.PUT_LINE('Error:' || SQLERRM);
            RAISE;
    END FIDE_TRANSPORTE_INSERTAR_SP;

