    -- ===== Reportes y procesos de negocio =====
    PROCEDURE FIDE_REPORTE_PEDIDOS_USUARIO_SP(P_USUARIO_ID IN NUMBER, P_CURSOR OUT SYS_REFCURSOR) IS
    BEGIN
        OPEN P_CURSOR FOR
            SELECT PEDIDO_ID, FECHA_PEDIDO, FECHA_ENTREGA, CLIENTE, DESCRIPCION_ESTADO, TOTAL_PEDIDO
            FROM FIDE_PEDIDOS_V
            WHERE USUARIO_ID = P_USUARIO_ID
            ORDER BY FECHA_PEDIDO DESC;
    EXCEPTION
        WHEN TOO_MANY_ROWS THEN
            DBMS_OUTPUT.PUT_LINE('Se encontraron varios registros');
            RAISE;
        WHEN NO_DATA_FOUND THEN
            DBMS_OUTPUT.PUT_LINE('No se encontraron datos');
            RAISE;
        WHEN OTHERS THEN
            DBMS_OUTPUT.PUT_LINE('Error:' || SQLERRM);
            RAISE;
    END FIDE_REPORTE_PEDIDOS_USUARIO_SP;

    PROCEDURE FIDE_REPORTE_INVENTARIO_BAJO_SP(P_MINIMO IN NUMBER, P_CURSOR OUT SYS_REFCURSOR) IS
    BEGIN
        OPEN P_CURSOR FOR
            SELECT INVENTARIO_ID, NOMBRE_PRODUCTO, CANTIDAD_INVE, TIPO_PRODUCTO, DESTINATARIO
            FROM FIDE_INVENTARIO_V
            WHERE CANTIDAD_INVE <= P_MINIMO
            ORDER BY CANTIDAD_INVE;
    EXCEPTION
        WHEN TOO_MANY_ROWS THEN
            DBMS_OUTPUT.PUT_LINE('Se encontraron varios registros');
            RAISE;
        WHEN NO_DATA_FOUND THEN
            DBMS_OUTPUT.PUT_LINE('No se encontraron datos');
            RAISE;
        WHEN OTHERS THEN
            DBMS_OUTPUT.PUT_LINE('Error:' || SQLERRM);
            RAISE;
    END FIDE_REPORTE_INVENTARIO_BAJO_SP;

    PROCEDURE FIDE_REPORTE_MANT_PENDIENTES_SP(P_CURSOR OUT SYS_REFCURSOR) IS
    BEGIN
        OPEN P_CURSOR FOR
            SELECT MANTENIMIENTO_ID, NOMBRE_ACTIVO, NOMBRE_MANTENIMIENTO, FECHA_PROGRAMADA, RESPONSABLE
            FROM FIDE_MANTENIMIENTO_V
            WHERE FECHA_PROGRAMADA >= TRUNC(SYSDATE)
            ORDER BY FECHA_PROGRAMADA;
    EXCEPTION
        WHEN TOO_MANY_ROWS THEN
            DBMS_OUTPUT.PUT_LINE('Se encontraron varios registros');
            RAISE;
        WHEN NO_DATA_FOUND THEN
            DBMS_OUTPUT.PUT_LINE('No se encontraron datos');
            RAISE;
        WHEN OTHERS THEN
            DBMS_OUTPUT.PUT_LINE('Error:' || SQLERRM);
            RAISE;
    END FIDE_REPORTE_MANT_PENDIENTES_SP;

    PROCEDURE FIDE_REPORTE_CONTROLES_PROX_SP(P_DIAS IN NUMBER, P_CURSOR OUT SYS_REFCURSOR) IS
    BEGIN
        OPEN P_CURSOR FOR
            SELECT CONTROL_SANITARIO_ID, NOMBRE_ACTIVO, NOMBRE_CONTROL, FECHA_PROXIMO_CONTROL,
                   FECHA_PROXIMO_CONTROL - TRUNC(SYSDATE) AS DIAS_RESTANTES
            FROM FIDE_CONTROL_SANITARIO_V
            WHERE FECHA_PROXIMO_CONTROL BETWEEN TRUNC(SYSDATE) AND TRUNC(SYSDATE) + P_DIAS
            ORDER BY FECHA_PROXIMO_CONTROL;
    EXCEPTION
        WHEN TOO_MANY_ROWS THEN
            DBMS_OUTPUT.PUT_LINE('Se encontraron varios registros');
            RAISE;
        WHEN NO_DATA_FOUND THEN
            DBMS_OUTPUT.PUT_LINE('No se encontraron datos');
            RAISE;
        WHEN OTHERS THEN
            DBMS_OUTPUT.PUT_LINE('Error:' || SQLERRM);
            RAISE;
    END FIDE_REPORTE_CONTROLES_PROX_SP;

    PROCEDURE FIDE_REPORTE_GANADO_LOTE_SP(P_LOTE_ID IN NUMBER, P_CURSOR OUT SYS_REFCURSOR) IS
    BEGIN
        OPEN P_CURSOR FOR
            SELECT GANADO_ID, NOMBRE_RAZA, EDAD, FECHA_REGISTRO,
                   FIDE_CANTIDAD_GANADO_LOTE_FN(LOTE_ID) AS TOTAL_EN_LOTE,
                   FIDE_EDAD_PROMEDIO_LOTE_FN(LOTE_ID) AS EDAD_PROMEDIO
            FROM FIDE_GANADO_V
            WHERE LOTE_ID = P_LOTE_ID
            ORDER BY GANADO_ID;
    EXCEPTION
        WHEN TOO_MANY_ROWS THEN
            DBMS_OUTPUT.PUT_LINE('Se encontraron varios registros');
            RAISE;
        WHEN NO_DATA_FOUND THEN
            DBMS_OUTPUT.PUT_LINE('No se encontraron datos');
            RAISE;
        WHEN OTHERS THEN
            DBMS_OUTPUT.PUT_LINE('Error:' || SQLERRM);
            RAISE;
    END FIDE_REPORTE_GANADO_LOTE_SP;

    -- P_CANTIDAD puede ser positiva (entrada) o negativa (salida)
    PROCEDURE FIDE_AJUSTAR_INVENTARIO_SP(P_INVENTARIO_ID IN NUMBER, P_CANTIDAD IN NUMBER) IS
    BEGIN
        UPDATE FIDE_INVENTARIO_TB
        SET CANTIDAD_INVE = CANTIDAD_INVE + P_CANTIDAD
        WHERE INVENTARIO_ID = P_INVENTARIO_ID;
        IF SQL%ROWCOUNT = 0 THEN
            RAISE_APPLICATION_ERROR(-20020, 'El inventario no existe');
        END IF;
        COMMIT;
    EXCEPTION
        WHEN TOO_MANY_ROWS THEN
            ROLLBACK;
            DBMS_OUTPUT.PUT_LINE('Se encontraron varios registros');
            RAISE;
        WHEN NO_DATA_FOUND THEN
            ROLLBACK;
            DBMS_OUTPUT.PUT_LINE('No se encontraron datos');
            RAISE;
        WHEN OTHERS THEN
            ROLLBACK;
            DBMS_OUTPUT.PUT_LINE('Error:' || SQLERRM);
            RAISE;
    END FIDE_AJUSTAR_INVENTARIO_SP;

    PROCEDURE FIDE_REGISTRAR_DETALLE_SP(P_PEDIDO_ID IN NUMBER, P_INVENTARIO_ID IN NUMBER,
                                        P_CANTIDAD IN NUMBER, P_PRECIO IN NUMBER, P_DETALLE_ID OUT NUMBER) IS
        V_STOCK  NUMBER;
        V_ACTIVO NUMBER;
    BEGIN
        V_STOCK := FIDE_STOCK_INVENTARIO_FN(P_INVENTARIO_ID);
        IF V_STOCK IS NULL THEN
            RAISE_APPLICATION_ERROR(-20020, 'El inventario no existe');
        END IF;
        IF P_CANTIDAD > V_STOCK THEN
            RAISE_APPLICATION_ERROR(-20021, 'Stock insuficiente. Disponible: ' || V_STOCK);
        END IF;
        V_ACTIVO := FIDE_ESTADO_ID_FN('ACTIVO');

        UPDATE FIDE_INVENTARIO_TB
        SET CANTIDAD_INVE = CANTIDAD_INVE - P_CANTIDAD
        WHERE INVENTARIO_ID = P_INVENTARIO_ID;

        -- el procedimiento CRUD hace el COMMIT de ambas operaciones
        FIDE_DETALLE_PEDIDOS_INSERTAR_SP(
            P_CANTIDAD_PEDIDO   => P_CANTIDAD,
            P_PRECIO_UNITARIO   => P_PRECIO,
            P_INVENTARIO_ID     => P_INVENTARIO_ID,
            P_PEDIDO_ID         => P_PEDIDO_ID,
            P_ESTADO_ID         => V_ACTIVO,
            P_DETALLE_PEDIDO_ID => P_DETALLE_ID);
    EXCEPTION
        WHEN TOO_MANY_ROWS THEN
            ROLLBACK;
            DBMS_OUTPUT.PUT_LINE('Se encontraron varios registros');
            RAISE;
        WHEN NO_DATA_FOUND THEN
            ROLLBACK;
            DBMS_OUTPUT.PUT_LINE('No se encontraron datos');
            RAISE;
        WHEN OTHERS THEN
            ROLLBACK;
            DBMS_OUTPUT.PUT_LINE('Error:' || SQLERRM);
            RAISE;
    END FIDE_REGISTRAR_DETALLE_SP;

    PROCEDURE FIDE_FACTURAR_SP(P_DESCRIPCION IN VARCHAR2, P_SUB_TOTAL IN NUMBER, P_CNT IN NUMBER,
                               P_NUMERO_ITEMS IN NUMBER, P_PORCENTAJE_IVA IN NUMBER, P_FACTURA_ID OUT NUMBER) IS
        V_PORC      NUMBER := NVL(P_PORCENTAJE_IVA, 13);
        V_TOTAL_IVA NUMBER;
        V_TOTAL     NUMBER;
        V_ACTIVO    NUMBER;
    BEGIN
        V_TOTAL_IVA := FIDE_CALCULAR_IVA_FN(P_SUB_TOTAL, V_PORC);
        V_TOTAL     := FIDE_TOTAL_CON_IVA_FN(P_SUB_TOTAL, V_PORC);
        V_ACTIVO    := FIDE_ESTADO_ID_FN('ACTIVO');
        FIDE_FACTURACION_INSERTAR_SP(
            P_FECHA_FACTURA => TRUNC(SYSDATE),
            P_DESCRIPCION   => P_DESCRIPCION,
            P_IVA           => V_PORC,
            P_CNT           => P_CNT,
            P_SUB_TOTAL     => P_SUB_TOTAL,
            P_TOTAL_IVA     => V_TOTAL_IVA,
            P_TOTAL         => V_TOTAL,
            P_NUMERO_ITEMS  => P_NUMERO_ITEMS,
            P_ESTADO_ID     => V_ACTIVO,
            P_FACTURA_ID    => P_FACTURA_ID);
    EXCEPTION
        WHEN TOO_MANY_ROWS THEN
            ROLLBACK;
            DBMS_OUTPUT.PUT_LINE('Se encontraron varios registros');
            RAISE;
        WHEN NO_DATA_FOUND THEN
            ROLLBACK;
            DBMS_OUTPUT.PUT_LINE('No se encontraron datos');
            RAISE;
        WHEN OTHERS THEN
            ROLLBACK;
            DBMS_OUTPUT.PUT_LINE('Error:' || SQLERRM);
            RAISE;
    END FIDE_FACTURAR_SP;

PROCEDURE FIDE_ESTADO_ID_SP(P_DESCRIPCION_ESTADO IN VARCHAR2, P_ESTADO_ID OUT NUMBER) IS
    BEGIN
        SELECT MAX(ESTADO_ID) INTO P_ESTADO_ID
        FROM FIDE_ESTADO_TB
        WHERE UPPER(DESCRIPCION_ESTADO) = UPPER(TRIM(P_DESCRIPCION_ESTADO));
    EXCEPTION
        WHEN OTHERS THEN
            DBMS_OUTPUT.PUT_LINE('Error:' || SQLERRM);
            RAISE;
    END FIDE_ESTADO_ID_SP;

    PROCEDURE FIDE_DESCRIPCION_ESTADO_SP(P_ESTADO_ID IN NUMBER, P_DESCRIPCION OUT VARCHAR2) IS
    BEGIN
        SELECT MAX(DESCRIPCION_ESTADO) INTO P_DESCRIPCION
        FROM FIDE_ESTADO_TB WHERE ESTADO_ID = P_ESTADO_ID;
    EXCEPTION
        WHEN OTHERS THEN
            DBMS_OUTPUT.PUT_LINE('Error:' || SQLERRM);
            RAISE;
    END FIDE_DESCRIPCION_ESTADO_SP;

    PROCEDURE FIDE_NOMBRE_USUARIO_SP(P_USUARIO_ID IN NUMBER, P_NOMBRE OUT VARCHAR2) IS
    BEGIN
        SELECT TRIM(MAX(NOMBRE_USUARIO || ' ' || APELLIDO_PATERNO || ' ' || APELLIDO_MATERNO))
        INTO P_NOMBRE
        FROM FIDE_USUARIOS_TB WHERE USUARIO_ID = P_USUARIO_ID;
    EXCEPTION
        WHEN OTHERS THEN
            DBMS_OUTPUT.PUT_LINE('Error:' || SQLERRM);
            RAISE;
    END FIDE_NOMBRE_USUARIO_SP;

    PROCEDURE FIDE_TOTAL_PEDIDO_SP(P_PEDIDO_ID IN NUMBER, P_TOTAL OUT NUMBER) IS
    BEGIN
        SELECT NVL(SUM(CANTIDAD_PEDIDO * PRECIO_UNITARIO), 0) INTO P_TOTAL
        FROM FIDE_DETALLE_PEDIDOS_TB WHERE PEDIDO_ID = P_PEDIDO_ID;
    EXCEPTION
        WHEN OTHERS THEN
            DBMS_OUTPUT.PUT_LINE('Error:' || SQLERRM);
            RAISE;
    END FIDE_TOTAL_PEDIDO_SP;

    PROCEDURE FIDE_CALCULAR_IVA_SP(P_MONTO IN NUMBER, P_PORCENTAJE IN NUMBER, P_IVA OUT NUMBER) IS
    BEGIN
        P_IVA := ROUND(P_MONTO * NVL(P_PORCENTAJE, 13) / 100, 2);
    EXCEPTION
        WHEN OTHERS THEN
            DBMS_OUTPUT.PUT_LINE('Error:' || SQLERRM);
            RAISE;
    END FIDE_CALCULAR_IVA_SP;

    PROCEDURE FIDE_TOTAL_CON_IVA_SP(P_MONTO IN NUMBER, P_PORCENTAJE IN NUMBER, P_TOTAL OUT NUMBER) IS
        V_IVA NUMBER;
    BEGIN
        FIDE_CALCULAR_IVA_SP(P_MONTO, P_PORCENTAJE, V_IVA);
        P_TOTAL := P_MONTO + V_IVA;
    EXCEPTION
        WHEN OTHERS THEN
            DBMS_OUTPUT.PUT_LINE('Error:' || SQLERRM);
            RAISE;
    END FIDE_TOTAL_CON_IVA_SP;

    PROCEDURE FIDE_STOCK_INVENTARIO_SP(P_INVENTARIO_ID IN NUMBER, P_STOCK OUT NUMBER) IS
    BEGIN
        -- NULL si el inventario no existe
        SELECT MAX(CANTIDAD_INVE) INTO P_STOCK
        FROM FIDE_INVENTARIO_TB WHERE INVENTARIO_ID = P_INVENTARIO_ID;
    EXCEPTION
        WHEN OTHERS THEN
            DBMS_OUTPUT.PUT_LINE('Error:' || SQLERRM);
            RAISE;
    END FIDE_STOCK_INVENTARIO_SP;

    PROCEDURE FIDE_CANTIDAD_GANADO_LOTE_SP(P_LOTE_ID IN NUMBER, P_CANTIDAD OUT NUMBER) IS
    BEGIN
        SELECT COUNT(*) INTO P_CANTIDAD FROM FIDE_GANADO_TB WHERE LOTE_ID = P_LOTE_ID;
    EXCEPTION
        WHEN OTHERS THEN
            DBMS_OUTPUT.PUT_LINE('Error:' || SQLERRM);
            RAISE;
    END FIDE_CANTIDAD_GANADO_LOTE_SP;

    PROCEDURE FIDE_EDAD_PROMEDIO_LOTE_SP(P_LOTE_ID IN NUMBER, P_PROMEDIO OUT NUMBER) IS
    BEGIN
        SELECT NVL(ROUND(AVG(EDAD), 2), 0) INTO P_PROMEDIO
        FROM FIDE_GANADO_TB WHERE LOTE_ID = P_LOTE_ID;
    EXCEPTION
        WHEN OTHERS THEN
            DBMS_OUTPUT.PUT_LINE('Error:' || SQLERRM);
            RAISE;
    END FIDE_EDAD_PROMEDIO_LOTE_SP;

    PROCEDURE FIDE_DIAS_PROXIMO_CONTROL_SP(P_ACTIVO_ID IN NUMBER, P_DIAS OUT NUMBER) IS
        V_FECHA DATE;
    BEGIN
        SELECT MIN(FECHA_PROXIMO_CONTROL) INTO V_FECHA
        FROM FIDE_CONTROL_SANITARIO_TB
        WHERE ACTIVO_ID = P_ACTIVO_ID AND FECHA_PROXIMO_CONTROL >= TRUNC(SYSDATE);
        -- NULL si no hay controles futuros
        IF V_FECHA IS NOT NULL THEN
            P_DIAS := TRUNC(V_FECHA) - TRUNC(SYSDATE);
        ELSE
            P_DIAS := NULL;
        END IF;
    EXCEPTION
        WHEN OTHERS THEN
            DBMS_OUTPUT.PUT_LINE('Error:' || SQLERRM);
            RAISE;
    END FIDE_DIAS_PROXIMO_CONTROL_SP;

    PROCEDURE FIDE_ITEMS_PEDIDO_SP(P_PEDIDO_ID IN NUMBER, P_ITEMS OUT NUMBER) IS
    BEGIN
        SELECT COUNT(*) INTO P_ITEMS FROM FIDE_DETALLE_PEDIDOS_TB WHERE PEDIDO_ID = P_PEDIDO_ID;
    EXCEPTION
        WHEN OTHERS THEN
            DBMS_OUTPUT.PUT_LINE('Error:' || SQLERRM);
            RAISE;
    END FIDE_ITEMS_PEDIDO_SP;

    PROCEDURE FIDE_TOTAL_KG_PEDIDO_SP(P_PEDIDO_ID IN NUMBER, P_KG OUT NUMBER) IS
    BEGIN
        SELECT NVL(SUM(CANTIDAD_KG), 0) INTO P_KG FROM FIDE_TRANSPORTE_TB WHERE PEDIDO_ID = P_PEDIDO_ID;
    EXCEPTION
        WHEN OTHERS THEN
            DBMS_OUTPUT.PUT_LINE('Error:' || SQLERRM);
            RAISE;
    END FIDE_TOTAL_KG_PEDIDO_SP;

    PROCEDURE FIDE_TELEFONOS_CONTACTO_SP(P_CONTACTO_ID IN NUMBER, P_TELEFONOS OUT VARCHAR2) IS
    BEGIN
        SELECT LISTAGG(NUMERO, ', ') WITHIN GROUP (ORDER BY TELEFONO_ID) INTO P_TELEFONOS
        FROM FIDE_TELEFONO_TB WHERE CONTACTO_ID = P_CONTACTO_ID;
    EXCEPTION
        WHEN OTHERS THEN
            DBMS_OUTPUT.PUT_LINE('Error:' || SQLERRM);
            RAISE;
    END FIDE_TELEFONOS_CONTACTO_SP;

    PROCEDURE FIDE_CORREOS_CONTACTO_SP(P_CONTACTO_ID IN NUMBER, P_CORREOS OUT VARCHAR2) IS
    BEGIN
        SELECT LISTAGG(DIRECCION_CORREO, ', ') WITHIN GROUP (ORDER BY CORREO_ID) INTO P_CORREOS
        FROM FIDE_CORREO_TB WHERE CONTACTO_ID = P_CONTACTO_ID;
    EXCEPTION
        WHEN OTHERS THEN
            DBMS_OUTPUT.PUT_LINE('Error:' || SQLERRM);
            RAISE;
    END FIDE_CORREOS_CONTACTO_SP;

    PROCEDURE FIDE_ACTIVOS_POR_TIPO_SP(P_TIPO_ACTIVO_ID IN NUMBER, P_CANTIDAD OUT NUMBER) IS
    BEGIN
        SELECT COUNT(*) INTO P_CANTIDAD FROM FIDE_ACTIVOS_TB WHERE TIPO_ACTIVO_ID = P_TIPO_ACTIVO_ID;
    EXCEPTION
        WHEN OTHERS THEN
            DBMS_OUTPUT.PUT_LINE('Error:' || SQLERRM);
            RAISE;
    END FIDE_ACTIVOS_POR_TIPO_SP;

    PROCEDURE FIDE_MONTO_CONTABLE_PEDIDO_SP(P_PEDIDO_ID IN NUMBER, P_MONTO OUT NUMBER) IS
    BEGIN
        SELECT NVL(SUM(MONTO), 0) INTO P_MONTO FROM FIDE_CONTABILIDAD_TB WHERE PEDIDO_ID = P_PEDIDO_ID;
    EXCEPTION
        WHEN OTHERS THEN
            DBMS_OUTPUT.PUT_LINE('Error:' || SQLERRM);
            RAISE;
    END FIDE_MONTO_CONTABLE_PEDIDO_SP;

    PROCEDURE FIDE_SECUENCIA_NUMERICA_SP(P_NUEVO_VALOR IN NUMBER, P_RESULTADO OUT NUMBER) IS
    BEGIN
        P_RESULTADO := TO_NUMBER(TO_CHAR(SYSDATE, 'YYYYMMDD') || LPAD(MOD(P_NUEVO_VALOR, 100000), 5, '0'));
    EXCEPTION
        WHEN OTHERS THEN
            DBMS_OUTPUT.PUT_LINE('Error:' || SQLERRM);
            RAISE;
    END FIDE_SECUENCIA_NUMERICA_SP;
END FIDE_PROYECTO_PCK;
/

-- Triggers de FIDE_PROYECTO (cada bloque termina con / para SQL Developer y APEX)

CREATE OR REPLACE TRIGGER FIDE_ESTADO_BIU_TRG
BEFORE INSERT OR UPDATE ON FIDE_ESTADO_TB
FOR EACH ROW
DECLARE
    V_ID NUMBER;
BEGIN
    IF INSERTING THEN
        IF :NEW.ESTADO_ID IS NULL THEN
            FIDE_PROYECTO_PCK.FIDE_SIGUIENTE_ID_SP('FIDE_ESTADO_SEQ', V_ID);
            :NEW.ESTADO_ID := V_ID;
        END IF;
        :NEW.AUD_CREADO_POR   := NVL(SYS_CONTEXT('USERENV','CLIENT_IDENTIFIER'), SYS_CONTEXT('USERENV','SESSION_USER'));
        :NEW.AUD_FECHA_CREACION := SYSTIMESTAMP;
        :NEW.AUD_ACCION       := 'INSERT';
    ELSIF UPDATING THEN
        :NEW.AUD_MODIFICADO_POR := NVL(SYS_CONTEXT('USERENV','CLIENT_IDENTIFIER'), SYS_CONTEXT('USERENV','SESSION_USER'));
        :NEW.AUD_FECHA_MODIFICACION := SYSTIMESTAMP;
        :NEW.AUD_ACCION       := 'UPDATE';
    END IF;
END FIDE_ESTADO_BIU_TRG;
/

