-- Validaciones de negocio
CREATE OR REPLACE TRIGGER FIDE_INVENTARIO_STOCK_TRG
BEFORE INSERT OR UPDATE OF CANTIDAD_INVE ON FIDE_INVENTARIO_TB
FOR EACH ROW
BEGIN
    IF :NEW.CANTIDAD_INVE < 0 THEN
        RAISE_APPLICATION_ERROR(-20010, 'El inventario no puede quedar en negativo');
    END IF;
END FIDE_INVENTARIO_STOCK_TRG;
/


CREATE OR REPLACE TRIGGER FIDE_PEDIDOS_FECHAS_TRG
BEFORE INSERT OR UPDATE ON FIDE_PEDIDOS_TB
FOR EACH ROW
BEGIN
    IF :NEW.FECHA_ENTREGA IS NOT NULL AND :NEW.FECHA_ENTREGA < :NEW.FECHA_PEDIDO THEN
        RAISE_APPLICATION_ERROR(-20011, 'La fecha de entrega no puede ser anterior a la fecha del pedido');
    END IF;
END FIDE_PEDIDOS_FECHAS_TRG;
/


CREATE OR REPLACE TRIGGER FIDE_DETALLE_PEDIDOS_VALIDA_TRG
BEFORE INSERT OR UPDATE ON FIDE_DETALLE_PEDIDOS_TB
FOR EACH ROW
BEGIN
    IF :NEW.CANTIDAD_PEDIDO <= 0 THEN
        RAISE_APPLICATION_ERROR(-20012, 'La cantidad del pedido debe ser mayor a cero');
    END IF;
    IF :NEW.PRECIO_UNITARIO < 0 THEN
        RAISE_APPLICATION_ERROR(-20013, 'El precio unitario no puede ser negativo');
    END IF;
END FIDE_DETALLE_PEDIDOS_VALIDA_TRG;
/

